let cfg,studentToken='',adminToken='',exam=null,qIndex=0,answers={},clock,proctorStream=null,proctorTimer=null,proctorActive=false,proctorBusy=false,lastFaceSeen=Date.now(),lastFaceWarning=0,importMode='olympiad';
const $=id=>document.getElementById(id),api=async(url,opt={})=>{const r=await fetch(url,{headers:{'content-type':'application/json',...(opt.token?{authorization:'Bearer '+opt.token}:{})},...opt});const j=await r.json();if(!r.ok)throw Error(j.error||'Қате');return j};
const memoryStore={},safeStore={get(k){try{return window.localStorage.getItem(k)}catch{}try{const m=document.cookie.match(new RegExp('(?:^|; )'+encodeURIComponent(k)+'=([^;]*)'));if(m)return decodeURIComponent(m[1])}catch{}return memoryStore[k]||null},set(k,v){memoryStore[k]=String(v);try{window.localStorage.setItem(k,String(v));return}catch{}try{document.cookie=`${encodeURIComponent(k)}=${encodeURIComponent(v)}; Path=/; Max-Age=604800; SameSite=Lax; Secure`}catch{}},remove(k){delete memoryStore[k];try{window.localStorage.removeItem(k)}catch{}try{document.cookie=`${encodeURIComponent(k)}=; Path=/; Max-Age=0; SameSite=Lax; Secure`}catch{}}};
function page(id){document.querySelectorAll('.page').forEach(x=>x.classList.toggle('hidden',x.id!==id));scrollTo(0,0)}function toast(t){$('toast').textContent=t;$('toast').classList.remove('hidden');setTimeout(()=>$('toast').classList.add('hidden'),2500)}
async function init(){cfg=await api('/api/config');const gradeOpts='<option value="">Таңдаңыз</option>'+cfg.grades.map(x=>`<option>${x}</option>`).join(''),subjectOpts='<option value="">Таңдаңыз</option>'+cfg.subjects.map(x=>`<option>${x}</option>`).join('');['regGrade','qGrade','aiGrade'].forEach(x=>$(x).innerHTML=gradeOpts);['regSubject','qSubject','aiSubject'].forEach(x=>$(x).innerHTML=subjectOpts);$('untCombo').innerHTML='<option value="">Таңдаңыз</option>'+cfg.untCombinations.map((x,i)=>`<option value="${i}">${x[0].startsWith('Шығармашылық')?'Шығармашылық бағыт (30 тапсырма, 70 минут)':`${h(x[0])} + ${h(x[1])}`}</option>`).join('');$('stem').innerHTML=cfg.subjects.slice(0,6).map(x=>`<span class="chip">${x}</span>`).join('');$('human').innerHTML=cfg.subjects.slice(6).map(x=>`<span class="chip">${x}</span>`).join('');await restoreSession()}
function studentDirection(s){return s?.profile1?.startsWith('Шығармашылық')?'Шығармашылық бағыт':s?.subject||''}
function examStudentLabel(){return exam?.examType==='unt'?`${exam.student.name} • ҰБТ • ${studentDirection(exam.student)}`:`${exam.student.name} • ${exam.student.grade}-сынып • ${exam.student.subject}`}
async function restoreSession(){const role=safeStore.get('moRole');if(role==='admin'&&(adminToken=safeStore.get('moAdminToken')||'')){try{$('adminLogin').classList.add('hidden');$('dashboard').classList.remove('hidden');page('admin');await loadDash();return}catch{safeStore.remove('moAdminToken')}}if(role==='student'&&(studentToken=safeStore.get('moStudentToken')||'')){try{exam=await api('/api/exam',{token:studentToken});qIndex=0;answers=exam.answers||{};$('examWho').textContent=examStudentLabel();page('exam');renderQ();startClock();startProctoring()}catch{safeStore.remove('moStudentToken');safeStore.remove('moRole')}}}
async function register(){try{const s=await api('/api/student/register',{method:'POST',body:JSON.stringify({name:$('regName').value,grade:$('regGrade').value,subject:$('regSubject').value})});$('codeBox').innerHTML=`Сіздің қатысу кодыңыз:<b>${s.code}</b>Кодты жоғалтпай сақтаңыз.`;$('codeBox').classList.remove('hidden');$('loginCode').value=s.code}catch(e){toast(e.message)}}
async function untRegister(){try{const value=$('untCombo').value,pair=value===''?null:cfg.untCombinations[Number(value)],s=await api('/api/unt/register',{method:'POST',body:JSON.stringify({name:$('untName').value,profile1:pair?.[0],profile2:pair?.[1]})});$('untCodeBox').innerHTML=`Сіздің ҰБТ қатысу кодыңыз:<b>${s.code}</b>Кодты жоғалтпай сақтаңыз.`;$('untCodeBox').classList.remove('hidden');$('untLoginCode').value=s.code}catch(e){toast(e.message)}}
async function studentLogin(mode='olympiad'){try{const codeId=mode==='unt'?'untLoginCode':'loginCode',x=await api('/api/student/login',{method:'POST',body:JSON.stringify({code:$(codeId).value})});studentToken=x.token;safeStore.set('moStudentToken',studentToken);safeStore.set('moRole','student');exam=await api('/api/exam',{token:studentToken});if(!exam.questions.length)throw Error('Бұл бағытқа сұрақтар әлі енгізілмеген');qIndex=0;answers=exam.answers||{};$('examWho').textContent=examStudentLabel();page('exam');renderQ();startClock();startProctoring()}catch(e){toast(e.message)}}
function answerLetter(i){return 'ABCDE'[i]||String(Number(i)+1)}
function questionImage(q,word=false){if(!q?.imageUrl&&!q?.image_url)return '';const raw=q.imageUrl||q.image_url,url=raw.startsWith('/')?location.origin+raw:raw,source=q.imageSource||q.image_source||'';return `<figure class="questionFigure${word?' wordFigure':''}"><img class="questionImage${word?' wordImage':''}" src="${h(url)}" alt="Сұраққа арналған сурет" loading="lazy">${source?`<figcaption>Дереккөз: ${h(source)}</figcaption>`:''}</figure>`}
function renderQ(){const q=exam.questions[qIndex];$('examTitle').textContent=q.text;$('question').innerHTML=questionImage(q)+q.options.map((o,i)=>`<label class="option"><input type="radio" name="answer" value="${i}" ${answers[q.id]===i?'checked':''} onchange="selectAnswer('${q.id}',${i})">${answerLetter(i)}) ${h(o)}</label>`).join('');$('qCount').textContent=`${qIndex+1} / ${exam.questions.length}`;$('bar').style.width=((qIndex+1)/exam.questions.length*100)+'%';$('nextBtn').textContent=qIndex===exam.questions.length-1?'Тестті аяқтау':'Келесі →'}
function selectAnswer(id,value){answers[id]=value;api('/api/exam/save',{method:'POST',token:studentToken,body:JSON.stringify({attemptId:exam.attemptId,answers:{[id]:value}})}).catch(()=>toast('Жауап уақытша сақталмады'))}
function prevQ(){if(qIndex>0){qIndex--;renderQ()}}function nextQ(){if(qIndex<exam.questions.length-1){qIndex++;renderQ()}else submitExam()}
function startClock(){clearInterval(clock);const end=new Date(exam.startedAt).getTime()+exam.durationMinutes*60000;const draw=()=>{let s=Math.max(0,Math.floor((end-Date.now())/1000));$('timer').textContent=String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');if(!s){clearInterval(clock);submitExam()}};draw();clock=setInterval(draw,1000)}
function proctorPanel(){let p=$('proctorPanel');if(p)return p;p=document.createElement('aside');p.id='proctorPanel';p.className='proctorPanel';p.innerHTML=`<div id="proctorMove" class="proctorMove">↕ Жылжыту <button id="proctorToggle" type="button" aria-label="Кішірейту">−</button></div><div class="proctorBody"><video id="proctorVideo" autoplay muted playsinline></video><div class="proctorInfo"><b>Бақылау қосулы</b><span id="proctorStatus">Камера іске қосылуда...</span><button id="cameraRetry" class="cameraRetry hidden" type="button">Камераны қайта қосу</button><small>Бейне жазылмайды және серверге жіберілмейді.</small><strong id="violationBadge">Ескерту: ${exam?.violationCount||0}/5</strong></div></div>`;$('exam').appendChild(p);enableProctorDrag(p);$('proctorToggle').onclick=e=>{e.stopPropagation();p.classList.toggle('minimized');$('proctorToggle').textContent=p.classList.contains('minimized')?'+':'−'};$('cameraRetry').onclick=e=>{e.stopPropagation();resumeProctorCamera(true)};return p}
function enableProctorDrag(p){const handle=p.querySelector('#proctorMove');let active=false,dx=0,dy=0;handle.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;active=true;const r=p.getBoundingClientRect();dx=e.clientX-r.left;dy=e.clientY-r.top;p.style.right='auto';p.style.bottom='auto';handle.setPointerCapture(e.pointerId);e.preventDefault()});handle.addEventListener('pointermove',e=>{if(!active)return;const maxX=Math.max(0,innerWidth-p.offsetWidth),maxY=Math.max(0,innerHeight-p.offsetHeight);p.style.left=Math.min(maxX,Math.max(0,e.clientX-dx))+'px';p.style.top=Math.min(maxY,Math.max(0,e.clientY-dy))+'px';e.preventDefault()});const stop=()=>active=false;handle.addEventListener('pointerup',stop);handle.addEventListener('pointercancel',stop)}
function updateViolationBadge(n){if(exam)exam.violationCount=Number(n)||0;const b=$('violationBadge');if(b)b.textContent=`Ескерту: ${exam?.violationCount||0}/5`}
async function reportProctor(type,detail=''){if(!proctorActive||proctorBusy||!exam?.attemptId)return;proctorBusy=true;try{const r=await api('/api/exam/proctor',{method:'POST',token:studentToken,keepalive:true,body:JSON.stringify({attemptId:exam.attemptId,type,detail})});updateViolationBadge(r.violationCount);if(r.ended){showExamResult(r,'5 рет сайттан шыққаныңыз үшін тест автоматты түрде аяқталды.')}else if(type==='page-hidden')alert(`Ескерту! Тест бетінен шығуға болмайды. ${r.violationCount}/5. 5-ретте тест автоматты аяқталады.`);else if(type==='face-missing')toast('Камерадан бет көрінбеді. Телефонға тік қараңыз.')}catch(e){if(!document.hidden)toast(e.message)}finally{proctorBusy=false}}
async function resumeProctorCamera(force=false){if(!proctorActive||document.hidden||!$('proctorPanel'))return;const video=$('proctorVideo'),retry=$('cameraRetry'),status=$('proctorStatus'),live=proctorStream?.getVideoTracks().some(t=>t.readyState==='live');if(live&&!force){try{await video.play();status.textContent='Камера қосулы';retry.classList.add('hidden');return}catch{}}try{proctorStream?.getTracks().forEach(t=>t.stop());if(!navigator.mediaDevices?.getUserMedia)throw Error('Бұл браузер камераны қолдамайды');proctorStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:320},height:{ideal:240}},audio:false});video.srcObject=proctorStream;await video.play().catch(()=>{});proctorStream.getVideoTracks().forEach(t=>t.addEventListener('ended',()=>{if(!document.hidden)setTimeout(()=>resumeProctorCamera(),500)}));status.textContent='Камера қайта қосылды';retry.classList.add('hidden');lastFaceSeen=Date.now()}catch(e){status.textContent='Камера өшіп қалды';retry.classList.remove('hidden');reportProctor('camera-off',e.message)}}
async function startProctoring(){stopProctoring();proctorPanel();updateViolationBadge(exam?.violationCount||0);lastFaceSeen=Date.now();proctorActive=true;await resumeProctorCamera(true);if('FaceDetector'in window){const detector=new FaceDetector({fastMode:true,maxDetectedFaces:1});proctorTimer=setInterval(async()=>{if(!proctorActive||document.hidden||!$('proctorVideo')?.videoWidth)return;try{const faces=await detector.detect($('proctorVideo'));if(faces.length)lastFaceSeen=Date.now();else if(Date.now()-lastFaceSeen>6000&&Date.now()-lastFaceWarning>15000){lastFaceWarning=Date.now();reportProctor('face-missing','Бет 6 секундтан артық кадрдан көрінбеді')}}catch{}},3000)}else if($('proctorStatus')?.textContent.includes('қосылды'))$('proctorStatus').textContent='Камера қосулы (бет тексерісі қолжетімсіз)'}
function stopProctoring(){proctorActive=false;proctorBusy=false;if(proctorTimer){clearInterval(proctorTimer);proctorTimer=null}if(proctorStream){proctorStream.getTracks().forEach(t=>t.stop());proctorStream=null}const p=$('proctorPanel');if(p)p.remove()}
document.addEventListener('visibilitychange',()=>{if(!proctorActive)return;if(document.hidden)reportProctor('page-hidden','Қосымша немесе браузер беті ауыстырылды');else setTimeout(()=>resumeProctorCamera(),500)});
function showExamResult(r,message=''){const canRetry=exam?.examType==='unt';proctorActive=false;clearInterval(clock);stopProctoring();safeStore.remove('moStudentToken');safeStore.remove('moRole');$('score').textContent=`${r.score} / ${r.total} (${r.percent}%)`;$('answerReview').innerHTML=(message?`<div class="proctorEnded">${h(message)}</div>`:'')+(r.review||[]).map((q,i)=>`<article class="reviewItem ${q.isCorrect?'correct':'wrong'}"><h4>${i+1}. ${h(q.text)}</h4>${questionImage(q)}<p><b>Сіздің жауабыңыз:</b> ${q.selected===null?'Жауап берілмеген':`${answerLetter(q.selected)}) ${h(q.options[q.selected])}`}</p>${q.isCorrect?'':`<p class="correctAnswer"><b>Дұрыс жауап:</b> ${answerLetter(q.correct)}) ${h(q.options[q.correct])}</p>`}<span>${q.isCorrect?'✓ Дұрыс':'✕ Қате'}</span></article>`).join('');$('retryUntBtn').classList.toggle('hidden',!canRetry);page('done')}
async function retryUntExam(){const code=exam?.student?.code;if(!code)return page('untRegister');try{const x=await api('/api/student/login',{method:'POST',body:JSON.stringify({code})});studentToken=x.token;safeStore.set('moStudentToken',studentToken);safeStore.set('moRole','student');exam=await api('/api/exam',{token:studentToken});qIndex=0;answers={};$('examWho').textContent=examStudentLabel();page('exam');renderQ();startClock();startProctoring()}catch(e){toast(e.message)}}
async function submitExam(){try{clearInterval(clock);proctorActive=false;const r=await api('/api/exam/submit',{method:'POST',token:studentToken,body:JSON.stringify({attemptId:exam.attemptId,answers})});showExamResult(r)}catch(e){proctorActive=true;toast(e.message)}}
async function adminLogin(){try{const r=await api('/api/admin/login',{method:'POST',body:JSON.stringify({login:$('adminUser').value,password:$('adminPass').value})});adminToken=r.token;safeStore.set('moAdminToken',adminToken);safeStore.set('moRole','admin');$('adminLogin').classList.add('hidden');$('dashboard').classList.remove('hidden');loadDash()}catch(e){toast(e.message)}}
function adminLogout(){if(!confirm('Әкімші кабинетінен шығасыз ба?'))return;adminToken='';window.dash=null;safeStore.remove('moAdminToken');safeStore.remove('moRole');$('dashboard').classList.add('hidden');$('adminLogin').classList.remove('hidden');$('adminPass').value='';page('admin');toast('Әкімші кабинетінен шықтыңыз')}
async function loadDash(){const d=await api('/api/admin/dashboard',{token:adminToken});window.dash=d;const students=d.students.filter(x=>x.examType!=='unt'),done=d.attempts.filter(x=>x.examType!=='unt'&&x.submittedAt),questions=d.questions.filter(x=>(x.exam_type||'olympiad')!=='unt');$('stats').innerHTML=`<div class="stat"><b>${students.length}</b><span>Олимпиада қатысушысы</span></div><div class="stat"><b>${done.length}</b><span>Олимпиаданы тапсырған</span></div><div class="stat"><b>${questions.length}</b><span>Олимпиада сұрағы</span></div><div class="stat"><b>${new Set(students.map(x=>x.subject)).size}</b><span>Белсенді пән</span></div>`;dashTab('results')}
function table(head,rows){return `<div class="table"><table><thead><tr>${head.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows||'<tr><td colspan="9">Әзірге мәлімет жоқ</td></tr>'}</tbody></table></div>`}
function h(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function dashTab(tab){const d=window.dash;if(tab==='results'){openResults()}else if(tab==='ranking'){openRanking()}else if(tab==='classes'){openClassRanking()}else if(tab==='questions'){$('dashContent').innerHTML=table(['Сынып','Пән','Сұрақ','Ұпай',''],d.questions.filter(q=>(q.exam_type||'olympiad')!=='unt').map(q=>`<tr><td>${q.grade}</td><td>${h(q.subject)}</td><td>${h(q.text)}</td><td>${q.points}</td><td><button class="danger" onclick="deleteQ('${q.id}')">Өшіру</button></td></tr>`).join(''))}else if(tab==='unt'){openUntAdmin()}else{$('dashContent').innerHTML=`<div class="box" style="margin:0;width:100%"><label>Мектеп атауы<input id="setSchool" value="${h(d.settings.school)}"></label><label>Олимпиада ұзақтығы (минут)<input id="setDuration" type="number" value="${d.settings.durationMinutes}"></label><p>ҰБТ уақыты ресми құрылымға сай 240 минут болып бекітілген.</p><button class="primary" style="margin-top:16px" onclick="saveSettings()">Сақтау</button></div>`}}
function openResults(){const grades='<option value="">Барлық сынып</option>'+cfg.grades.map(g=>`<option value="${g}">${g}-сынып</option>`).join('');$('dashContent').innerHTML=`<div class="resultFilters"><label>Сынып<select id="resultGrade" onchange="renderResults()">${grades}</select></label><button class="primary" onclick="downloadAllEvidence()">Таңдалған сыныпты Word-пен жүктеу</button><span>Жалпы тізім және әр оқушының қате жауаптары бір құжатқа енгізіледі.</span></div><div id="resultsArea"></div>`;renderResults()}
function evidenceItems(){const d=window.dash,g=Number($('resultGrade')?.value||0);return d.attempts.filter(a=>a.examType!=='unt'&&a.submittedAt).map(a=>({a,s:d.students.find(x=>x.id===a.studentId)})).filter(x=>x.s&&(!g||x.s.grade===g))}
function renderResults(){const items=evidenceItems();$('resultsArea').innerHTML=table(['Оқушы','Сынып','Пән','Ұпай','Пайыз','Сайттан шығу','Уақыты','Дәлелдеме'],items.map(({a,s})=>`<tr><td>${h(s.name)}</td><td>${s.grade}</td><td>${h(s.subject)}</td><td>${a.score}/${a.total}</td><td>${Math.round(a.score/a.total*100)||0}%</td><td><b class="${a.violationCount?'warningText':''}">${a.violationCount||0}/5</b></td><td>${new Date(a.submittedAt).toLocaleString('kk-KZ')}</td><td><button class="secondary compact" onclick="downloadStudentAnalysis('${a.id}')">Жеке Word</button></td></tr>`).join(''))}
function classRankingData(){const d=window.dash,done=d.attempts.filter(a=>a.examType!=='unt'&&a.submittedAt).map(a=>({a,s:d.students.find(x=>x.id===a.studentId)})).filter(x=>x.s),rows=cfg.grades.map(grade=>{const items=done.filter(x=>x.s.grade===grade),subjectMap=new Map;for(const x of items){const p=x.a.total?x.a.score/x.a.total*100:0,entry=subjectMap.get(x.s.subject)||{values:[],score:0,total:0};entry.values.push(p);entry.score+=Number(x.a.score)||0;entry.total+=Number(x.a.total)||0;subjectMap.set(x.s.subject,entry)}const subjects=[...subjectMap].map(([name,x])=>({name,count:x.values.length,score:x.score,total:x.total,avg:x.values.reduce((a,b)=>a+b,0)/x.values.length})).sort((a,b)=>b.avg-a.avg||a.name.localeCompare(b.name,'kk')),percents=items.map(x=>x.a.total?x.a.score/x.a.total*100:0);return {grade,items,subjects,count:items.length,avg:percents.length?percents.reduce((a,b)=>a+b,0)/percents.length:null,best:percents.length?Math.max(...percents):null,low:percents.length?Math.min(...percents):null,strong:subjects[0]||null,weak:subjects.at(-1)||null}}),ranked=rows.filter(x=>x.count).sort((a,b)=>b.avg-a.avg||b.count-a.count);ranked.forEach((x,i)=>x.place=i+1);return rows}
function classWeakQuestions(row){const stats=new Map;for(const {a,s} of row.items){for(const q of attemptQuestions(a)){const key=q.id||`${s.subject}:${q.text}`,raw=a.answers?.[q.id],selected=Number.isInteger(Number(raw))?Number(raw):null,correct=Number(q.correct),x=stats.get(key)||{subject:s.subject,text:q.text,seen:0,wrong:0};x.seen++;if(selected!==correct)x.wrong++;stats.set(key,x)}}return [...stats.values()].filter(x=>x.wrong).map(x=>({...x,rate:Math.round(x.wrong/x.seen*100)})).sort((a,b)=>b.rate-a.rate||b.wrong-a.wrong).slice(0,5)}
function subjectBadges(x){return x.subjects.length?x.subjects.map(s=>`<span class="subjectScore">${h(s.name)} <b>${Math.round(s.avg)}%</b></span>`).join(''):'—'}
function classRankingTable(rows){return table(['Орын','Сынып','Қатысушы','Орташа нәтиже','Ең жоғары','Ең төмен','Барлық пәндер нәтижесі'],rows.slice().sort((a,b)=>(a.place||99)-(b.place||99)||a.grade-b.grade).map(x=>`<tr><td><b>${x.place||'—'}</b></td><td><b>${x.grade}-сынып</b></td><td>${x.count}</td><td>${x.avg===null?'—':Math.round(x.avg)+'%'}</td><td>${x.best===null?'—':Math.round(x.best)+'%'}</td><td>${x.low===null?'—':Math.round(x.low)+'%'}</td><td><div class="subjectScores">${subjectBadges(x)}</div></td></tr>`).join(''))}
function openClassRanking(){const rows=classRankingData(),details=rows.filter(x=>x.count).map(x=>{const weak=classWeakQuestions(x),subjects=x.subjects.slice().sort((a,b)=>cfg.subjects.indexOf(a.name)-cfg.subjects.indexOf(b.name)),subjectRows=subjects.map((s,i)=>`<tr><td>${i+1}</td><td>${h(s.name)}</td><td>${s.count}</td><td>${s.score}/${s.total}</td><td><b>${Math.round(s.avg)}%</b></td></tr>`).join('');return `<article class="classAnalysis"><h3>${x.grade}-сынып: барлық пәндер бойынша талдау</h3><p>Сыныптың орташа нәтижесі: <b>${Math.round(x.avg)}%</b>. Ең жоғары пән: <b>${h(x.strong?.name||'—')} ${x.strong?`(${Math.round(x.strong.avg)}%)`:''}</b>. Төмен пән: <b>${h(x.weak?.name||'—')} ${x.weak?`(${Math.round(x.weak.avg)}%)`:''}</b>.</p>${table(['№','Пән','Қатысушы','Жалпы ұпай','Орташа пайыз'],subjectRows)}<h4>Ең көп қате кеткен сұрақтар</h4>${weak.length?table(['Пән','Сұрақ','Қате саны','Қате пайызы'],weak.map(q=>`<tr><td>${h(q.subject)}</td><td>${h(q.text)}</td><td>${q.wrong}/${q.seen}</td><td><b>${q.rate}%</b></td></tr>`).join('')):'<p>Қате сұрақтар анықталмады.</p>'}</article>`}).join('');$('dashContent').innerHTML=`<div class="classRankHead"><div><h3>Сыныптар рейтингі</h3><p>Орын барлық тапсырған оқушылардың орташа пайызы бойынша есептеледі. Әр сыныптың барлық пәні төменде көрсетілген.</p></div><button class="primary" onclick="downloadClassRankingWord()">Word жүктеу</button></div>${classRankingTable(rows)}<h3 class="analysisTitle">Сыныптар мен пәндердің толық талдауы</h3>${details||'<div class="result">Әзірге тапсырған оқушылар жоқ.</div>'}`}
function downloadClassRankingWord(){const d=window.dash,rows=classRankingData(),rankRows=rows.slice().sort((a,b)=>(a.place||99)-(b.place||99)||a.grade-b.grade).map(x=>`<tr><td class="center">${x.place||'—'}</td><td class="center">${x.grade}</td><td class="center">${x.count}</td><td class="center">${x.avg===null?'—':Math.round(x.avg)+'%'}</td><td>${x.subjects.length?x.subjects.map(s=>`${h(s.name)} - ${Math.round(s.avg)}%`).join('<br>'):'—'}</td></tr>`).join(''),details=rows.filter(x=>x.count).map(x=>{const weak=classWeakQuestions(x),subjectRows=x.subjects.slice().sort((a,b)=>cfg.subjects.indexOf(a.name)-cfg.subjects.indexOf(b.name)).map((s,i)=>`<tr><td class="center">${i+1}</td><td>${h(s.name)}</td><td class="center">${s.count}</td><td class="center">${s.score}/${s.total}</td><td class="center">${Math.round(s.avg)}%</td></tr>`).join(''),qRows=weak.map(q=>`<tr><td>${h(q.subject)}</td><td>${h(q.text)}</td><td class="center">${q.wrong}/${q.seen}</td><td class="center">${q.rate}%</td></tr>`).join();return `<section class="page"><h2>${x.grade}-СЫНЫПТЫҢ ПӘНДЕР БОЙЫНША ТАЛДАУЫ</h2><p><b>Орташа нәтиже:</b> ${Math.round(x.avg)}%. <b>Ең жоғары пән:</b> ${h(x.strong?.name||'—')} ${x.strong?`(${Math.round(x.strong.avg)}%)`:''}. <b>Төмен пән:</b> ${h(x.weak?.name||'—')} ${x.weak?`(${Math.round(x.weak.avg)}%)`:''}.</p><table><thead><tr><th>№</th><th>Пән</th><th>Қатысушы</th><th>Жалпы ұпай</th><th>Орташа пайыз</th></tr></thead><tbody>${subjectRows}</tbody></table><h3>Ең көп қате кеткен сұрақтар</h3><table><thead><tr><th>Пән</th><th>Сұрақ</th><th>Қате саны</th><th>Қате пайызы</th></tr></thead><tbody>${qRows||'<tr><td colspan="4">Қате сұрақтар жоқ</td></tr>'}</tbody></table></section>`}).join(''),body=`<h1>${h(d.settings.school||'Егемқұл Тасанбаев атындағы ЖББМ')}</h1><h2>СЫНЫПТАР РЕЙТИНГІ ЖӘНЕ БАРЛЫҚ ПӘНДЕРДІҢ НӘТИЖЕ ТАЛДАУЫ</h2><p class="center">Рейтинг орташа пайыз бойынша есептелді. ${new Date().toLocaleDateString('kk-KZ')}</p><table><thead><tr><th>Орын</th><th>Сынып</th><th>Қатысушы</th><th>Орташа</th><th>Барлық пәндер нәтижесі</th></tr></thead><tbody>${rankRows}</tbody></table>${details}`;wordDownload(`Сыныптар_барлық_пәндер_рейтингі_${new Date().toISOString().slice(0,10)}.doc`,wordDocument(body,'Сыныптар және барлық пәндер рейтингі'))}

function attemptQuestions(a){if(Array.isArray(a.questionSnapshot)&&a.questionSnapshot.length)return a.questionSnapshot;const byId=new Map((window.dash.questions||[]).map(q=>[q.id,q]));return (a.questionIds||[]).map(id=>byId.get(id)).filter(Boolean)}
function safeName(v){return String(v||'құжат').replace(/[^\p{L}\p{N}]+/gu,'_').replace(/^_+|_+$/g,'')}
function wordDownload(filename,html){const blob=new Blob(['\ufeff',html],{type:'application/msword;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
function evidenceStyle(){return `<style>@page{size:A4;margin:1.4cm}body{font-family:"Times New Roman",serif;font-size:11pt;color:#111}h1,h2,h3{text-align:center;margin:7px 0}h1{font-size:15pt}h2{font-size:13pt}h3{font-size:12pt}.meta{margin:12px 0}.meta p{margin:5px 0}table{width:100%;border-collapse:collapse;margin:12px 0}th,td{border:1px solid #000;padding:5px;vertical-align:top}th{text-align:center;background:#eee}.center{text-align:center}.correct{color:#08753d;font-weight:bold}.wrong{color:#b42318;font-weight:bold}.page{page-break-before:always}.sign{margin-top:24px}.sign p{margin:10px 0}.wordImage{display:block;max-width:280px;max-height:180px;margin:7px auto}</style>`}
function studentEvidenceBody(a,s,pageBreak=false){const qs=attemptQuestions(a),rows=qs.map((q,i)=>{const raw=a.answers?.[q.id],selected=Number.isInteger(Number(raw))?Number(raw):null,correct=Number(q.correct),ok=selected===correct,studentAnswer=selected===null?'Жауап берілмеген':`${answerLetter(selected)}) ${h(q.options?.[selected]??'')}`,right=`${answerLetter(correct)}) ${h(q.options?.[correct]??'')}`;return `<tr><td class="center">${i+1}</td><td>${h(q.text)}${questionImage(q,true)}</td><td>${studentAnswer}</td><td>${right}</td><td class="center ${ok?'correct':'wrong'}">${ok?'Дұрыс':'Қате'}</td></tr>`}).join(''),percent=a.total?Math.round(a.score/a.total*100):0,duration=Math.max(0,Math.round((new Date(a.submittedAt)-new Date(a.startedAt))/1000)),jury=window.dash.settings.jury||{},events=(a.proctorEvents||[]).map(e=>`<tr><td>${new Date(e.at).toLocaleString('kk-KZ')}</td><td>${h(e.type==='page-hidden'?'Сайттан/қосымшадан шығу':e.type==='face-missing'?'Бет кадрдан көрінбеді':e.type==='camera-denied'?'Камераға рұқсат берілмеді':'Камера өшті')}</td><td>${h(e.detail||'')}</td></tr>`).join('');return `<section class="${pageBreak?'page':''}"><h1>${h(window.dash.settings.school||'Егемқұл Тасанбаев атындағы ЖББМ')}</h1><h2>${s.examType==='unt'?'ҰБТ СЫНАҚ':'ОҚУШЫНЫҢ ТЕСТ'} НӘТИЖЕСІ ЖӘНЕ ЖАУАПТАР ТАЛДАУЫ</h2><div class="meta"><p><b>Оқушы:</b> ${h(s.name)}</p><p><b>Сынып:</b> ${s.grade} &nbsp;&nbsp; <b>${s.examType==='unt'?'Бағыты':'Пән'}:</b> ${h(studentDirection(s))}</p><p><b>Қатысу коды:</b> ${h(s.code)} &nbsp;&nbsp; <b>Тапсырған уақыты:</b> ${new Date(a.submittedAt).toLocaleString('kk-KZ')}</p><p><b>Нәтиже:</b> ${a.score}/${a.total} (${percent}%) &nbsp;&nbsp; <b>Жұмсаған уақыты:</b> ${Math.floor(duration/60)} мин ${duration%60} сек</p><p><b>Сайттан шығу ескертуі:</b> ${a.violationCount||0}/5</p></div><table><thead><tr><th>№</th><th>Сұрақ</th><th>Оқушы жауабы</th><th>Дұрыс жауап</th><th>Нәтиже</th></tr></thead><tbody>${rows||'<tr><td colspan="5">Сұрақтар сақталмаған</td></tr>'}</tbody></table><p><b>Жиналған ұпай:</b> ${a.score}/${a.total}.</p>${events?`<h3>Бақылау журналы</h3><table><thead><tr><th>Уақыты</th><th>Оқиға</th><th>Түсініктеме</th></tr></thead><tbody>${events}</tbody></table>`:''}<div class="sign"><p>Тексеруші мұғалім: ______________________________ / __________ /</p><p>Комиссия төрағасы: ${h(jury.chair||'______________________________')} / __________ /</p><p>Хатшы: ${h(jury.secretary||'________________________________________')} / __________ /</p></div></section>`}
function wordDocument(body,title='Олимпиада нәтижелері'){return `<!doctype html><html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" lang="kk"><head><meta charset="utf-8"><title>${h(title)}</title>${evidenceStyle()}</head><body>${body}</body></html>`}
function downloadStudentAnalysis(attemptId){const a=window.dash.attempts.find(x=>x.id===attemptId),s=a&&window.dash.students.find(x=>x.id===a.studentId);if(!a||!s)return toast('Оқушы нәтижесі табылмады');wordDownload(`Жеке_талдау_${safeName(s.name)}_${s.grade}-сынып.doc`,wordDocument(studentEvidenceBody(a,s),`${s.name} нәтижесі`))}
function downloadAllEvidence(){const d=window.dash,items=evidenceItems(),grade=Number($('resultGrade')?.value||0),gradeText=grade?`${grade}-сынып`:'Барлық сынып';if(!items.length)return toast(`${gradeText} бойынша тапсырған оқушылар жоқ`);const summary=items.map((x,i)=>`<tr><td class="center">${i+1}</td><td>${h(x.s.name)}</td><td class="center">${x.s.grade}</td><td>${h(x.s.subject)}</td><td class="center">${x.a.score}/${x.a.total}</td><td class="center">${Math.round(x.a.score/x.a.total*100)||0}%</td><td>${new Date(x.a.submittedAt).toLocaleString('kk-KZ')}</td></tr>`).join(''),cover=`<h1>${h(d.settings.school||'Егемқұл Тасанбаев атындағы ЖББМ')}</h1><h2>${h(gradeText.toUpperCase())} - МЕКТЕПІШІЛІК ПӘН ОЛИМПИАДАСЫНЫҢ НӘТИЖЕЛЕРІ</h2><p class="center">Құжат жасалған күн: ${new Date().toLocaleString('kk-KZ')}</p><table><thead><tr><th>№</th><th>Оқушы</th><th>Сынып</th><th>Пән</th><th>Ұпай</th><th>Пайыз</th><th>Тапсырған уақыт</th></tr></thead><tbody>${summary}</tbody></table><p><b>Барлығы тапсырған:</b> ${items.length} оқушы.</p>`,details=items.map(x=>studentEvidenceBody(x.a,x.s,true)).join(''),filename=grade?`Олимпиада_${grade}-сынып_нәтижелері_${new Date().toISOString().slice(0,10)}.doc`:`Олимпиада_барлық_сынып_нәтижелері_${new Date().toISOString().slice(0,10)}.doc`;wordDownload(filename,wordDocument(cover+details,`${gradeText} нәтижелері және дәлелдеме`))}
function openRanking(){const gradeOpts=cfg.grades.map(x=>`<option value="${x}" ${x===5?'selected':''}>${x}-сынып</option>`).join(''),subjectOpts='<option value="">Барлық пән</option>'+cfg.subjects.map(x=>`<option>${h(x)}</option>`).join(''),j=window.dash.settings.jury||{};$('dashContent').innerHTML=`<div class="box juryBox" style="margin:0 0 18px;width:100%"><h3>Қазылар алқасы</h3><div class="row"><label>Төраға<input id="juryChair" value="${h(j.chair||'')}" placeholder="Аты-жөні"></label><label>Хатшы<input id="jurySecretary" value="${h(j.secretary||'')}" placeholder="Аты-жөні"></label></div><label>Комиссия мүшелері<textarea id="juryMembers" placeholder="Әр мүшені жаңа жолдан жазыңыз">${h(j.members||'')}</textarea></label><button class="secondary" onclick="saveJury()">Қазылар алқасын сақтау</button></div><div class="rankingFilters"><label>Сынып<select id="rankGrade" onchange="renderRanking()">${gradeOpts}</select></label><label>Пән<select id="rankSubject" onchange="renderRanking()">${subjectOpts}</select></label><button class="secondary" onclick="downloadProtocolWord()">Word жүктеу</button><button class="primary" onclick="printProtocol()">PDF / басып шығару</button></div><div id="rankingArea"></div>`;renderRanking()}
function juryValues(){const saved=window.dash.settings.jury||{};return {chair:$('juryChair')?.value.trim()||saved.chair||'',secretary:$('jurySecretary')?.value.trim()||saved.secretary||'',members:$('juryMembers')?.value.trim()||saved.members||''}}
function rankingRows(){const d=window.dash,g=Number($('rankGrade').value),sub=$('rankSubject').value,items=d.attempts.filter(a=>a.examType!=='unt'&&a.submittedAt).map(a=>({a,s:d.students.find(x=>x.id===a.studentId)})).filter(x=>x.s&&x.s.grade===g&&(!sub||x.s.subject===sub));items.sort((x,y)=>x.s.subject.localeCompare(y.s.subject,'kk')||(y.a.score/y.a.total-x.a.score/x.a.total)||(new Date(x.a.submittedAt)-new Date(x.a.startedAt))-(new Date(y.a.submittedAt)-new Date(y.a.startedAt)));let subject='',place=0,index=0,last='';for(const x of items){if(x.s.subject!==subject){subject=x.s.subject;place=0;index=0;last=''}index++;const key=`${x.a.score}/${x.a.total}`;if(key!==last)place=index;last=key;x.place=place;x.percent=Math.round(x.a.score/x.a.total*100);x.seconds=Math.max(0,Math.round((new Date(x.a.submittedAt)-new Date(x.a.startedAt))/1000))}return items}
function rankTable(items){return table(['Орын','Оқушы','Сынып','Пән','Ұпай','Пайыз','Жұмсаған уақыт'],items.map(x=>`<tr><td><b>${x.place}</b></td><td>${h(x.s.name)}</td><td>${x.s.grade}</td><td>${h(x.s.subject)}</td><td>${x.a.score}/${x.a.total}</td><td>${x.percent}%</td><td>${Math.floor(x.seconds/60)} мин ${x.seconds%60} сек</td></tr>`).join(''))}
function renderRanking(){const items=rankingRows();$('rankingArea').innerHTML=items.length?rankTable(items):'<div class="result">Бұл сынып бойынша тапсырған оқушылар әзірге жоқ.</div>'}
function printProtocol(){const items=rankingRows(),g=Number($('rankGrade').value),sub=$('rankSubject').value||'Барлық пән',school=window.dash.settings.school||'Егемқұл Тасанбаев атындағы ЖББМ',now=new Date(),date=now.toLocaleDateString('kk-KZ',{year:'numeric',month:'long',day:'numeric'}),times=items.flatMap(x=>[new Date(x.a.startedAt),new Date(x.a.submittedAt)]).filter(x=>!isNaN(x)),start=times.length?new Date(Math.min(...times)).toLocaleTimeString('kk-KZ',{hour:'2-digit',minute:'2-digit'}):'____',end=times.length?new Date(Math.max(...times)).toLocaleTimeString('kk-KZ',{hour:'2-digit',minute:'2-digit'}):'____',rows=items.map((x,i)=>`<tr><td>${i+1}</td><td class="name">${h(x.s.name)}</td><td>${h(x.s.subject)}</td><td>${x.a.score}/${x.a.total} (${x.percent}%)</td><td>${x.place} орын</td></tr>`).join(''),w=open('','_blank');w.document.write(`<!doctype html><html lang="kk"><head><meta charset="utf-8"><title>${g}-сынып олимпиада хаттамасы</title><link rel="icon" href="/favicon.svg" type="image/svg+xml"><style>@page{size:A4;margin:14mm 16mm}*{box-sizing:border-box}body{font:11.5pt "Times New Roman",serif;color:#111;line-height:1.25;max-width:190mm;margin:auto}h1,h2,p{margin:0}h1{font-size:14pt;text-align:center;line-height:1.25}h2{font-size:16pt;text-align:center;margin:5px 0 10px}.intro{text-align:center;margin-bottom:10px}.details{margin:12px 0}.details p{margin:5px 0}.line{display:inline-block;min-width:65px;border-bottom:1px solid #111;text-align:center;font-weight:bold}table{width:100%;border-collapse:collapse;margin:12px 0 20px;page-break-inside:auto}tr{page-break-inside:avoid}th,td{border:1px solid #111;padding:5px 6px;text-align:center;vertical-align:middle}th{font-weight:bold}.name{text-align:left}.notes{margin-top:18px}.rule{border-bottom:1px solid #111;height:24px}.dates{margin-top:20px}.dates p{margin:7px 0}.signatures{margin-top:18px}.signatures p{margin:9px 0}.no-print{text-align:right;margin-bottom:12px}.no-print button{padding:9px 14px;border:0;border-radius:7px;background:#0a55ad;color:#fff;font:10pt Arial;cursor:pointer}@media print{.no-print{display:none}}</style></head><body><div class="no-print"><button onclick="print()">Басып шығару / PDF сақтау</button></div><h1>${h(school)}<br>${g}-сынып оқушылары арасында өткізілген мектепішілік пән олимпиадасының</h1><h2>ҚОРЫТЫНДЫ ХАТТАМАСЫ</h2><p class="intro">Пәні: <b>${h(sub)}</b></p><div class="details"><p>Олимпиада комиссиясының төрағасы: __________________________________________</p><p>Комиссия мүшелері: _________________________________________________________</p><p>Хатшы: ____________________________________________________________________</p><p>Олимпиадаға <span class="line">${items.length}</span> оқушы қатысты</p><p>Олимпиада <span class="line">${start}</span> сағатта басталды, <span class="line">${end}</span> сағатта аяқталды.</p></div><table><thead><tr><th style="width:7%">Р/с</th><th style="width:35%">Олимпиадаға қатысушының аты-жөні</th><th style="width:20%">Пән</th><th style="width:23%">Жалпы ұпай</th><th style="width:15%">Орын</th></tr></thead><tbody>${rows||'<tr><td colspan="5">Нәтиже жоқ</td></tr>'}</tbody></table><div class="notes">Комиссия мүшелерінің жеке оқушылардың жұмысы туралы ерекше пікірлері<div class="rule"></div><div class="rule"></div></div><div class="dates"><p>Олимпиада өткізу күні: ${h(date)}</p><p>Бағаларды хаттамаға жазу күні: ${h(date)}</p></div><div class="signatures"><p>Олимпиада комиссиясының төрағасы: ____________________ / __________ /</p><p>Олимпиаданы тексеруші мұғалім: _______________________ / __________ /</p><p>Комиссия мүшелері: __________________________________ / __________ /</p><p>Хатшы: ______________________________________________ / __________ /</p></div></body></html>`);w.document.close()}
function downloadProtocolWord(){const items=rankingRows(),g=Number($('rankGrade').value),sub=$('rankSubject').value||'Барлық пән',school=window.dash.settings.school||'Егемқұл Тасанбаев атындағы ЖББМ',date=new Date().toLocaleDateString('kk-KZ',{year:'numeric',month:'long',day:'numeric'}),rows=items.map((x,i)=>`<tr><td>${i+1}</td><td>${h(x.s.name)}</td><td>${h(x.s.subject)}</td><td>${x.a.score}/${x.a.total} (${x.percent}%)</td><td>${x.place} орын</td></tr>`).join('')||'<tr><td colspan="5">Нәтиже жоқ</td></tr>',doc=`<!doctype html><html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" lang="kk"><head><meta charset="utf-8"><title>Хаттама</title><style>@page{size:A4;margin:1.5cm}body{font-family:"Times New Roman";font-size:12pt}h1{text-align:center;font-size:14pt}h2{text-align:center;font-size:16pt}p{margin:8px 0}table{width:100%;border-collapse:collapse;margin:14px 0}th,td{border:1px solid #000;padding:6px;text-align:center}td:nth-child(2){text-align:left}.line{border-bottom:1px solid #000;height:24px}</style></head><body><h1>${h(school)}<br>${g}-сынып оқушылары арасында өткізілген мектепішілік пән олимпиадасының</h1><h2>ҚОРЫТЫНДЫ ХАТТАМАСЫ</h2><p style="text-align:center">Пәні: <b>${h(sub)}</b></p><p>Олимпиада комиссиясының төрағасы: __________________________________________</p><p>Комиссия мүшелері: _________________________________________________________</p><p>Хатшы: ____________________________________________________________________</p><p>Олимпиадаға <b>${items.length}</b> оқушы қатысты.</p><table><thead><tr><th>Р/с</th><th>Олимпиадаға қатысушының аты-жөні</th><th>Пән</th><th>Жалпы ұпай</th><th>Орын</th></tr></thead><tbody>${rows}</tbody></table><p>Комиссия мүшелерінің ерекше пікірлері:</p><div class="line"></div><div class="line"></div><p>Олимпиада өткізу күні: ${h(date)}</p><p>Бағаларды хаттамаға жазу күні: ${h(date)}</p><br><p>Олимпиада комиссиясының төрағасы: ____________________ / __________ /</p><p>Олимпиаданы тексеруші мұғалім: _______________________ / __________ /</p><p>Комиссия мүшелері: __________________________________ / __________ /</p><p>Хатшы: ______________________________________________ / __________ /</p></body></html>`,blob=new Blob(['\ufeff',doc],{type:'application/msword;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`Хаттама_${g}-сынып_${sub.replace(/[^\p{L}\p{N}]+/gu,'_')}.doc`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function untAdminData(){const d=window.dash,students=d.students.filter(s=>s.examType==='unt'),attempts=d.attempts.filter(a=>a.examType==='unt'),questions=d.questions.filter(q=>(q.exam_type||'olympiad')==='unt');return {students,attempts,questions}}
function untRankingItems(){const {students,attempts}=untAdminData(),items=attempts.filter(a=>a.submittedAt).map(a=>({a,s:students.find(x=>x.id===a.studentId)})).filter(x=>x.s);items.forEach(x=>x.percent=x.a.total?Math.round(x.a.score/x.a.total*100):0);items.sort((x,y)=>(y.percent-x.percent)||(y.a.score-y.a.score)||((new Date(x.a.submittedAt)-new Date(x.a.startedAt))-(new Date(y.a.submittedAt)-new Date(y.a.startedAt))));let last='',place=0;items.forEach((x,i)=>{const key=`${x.percent}:${x.a.score}/${x.a.total}`;if(key!==last)place=i+1;last=key;x.place=place;x.seconds=Math.max(0,Math.round((new Date(x.a.submittedAt)-new Date(x.a.startedAt))/1000))});return items}
function untReadinessRows(questions){const count=(subject,points)=>questions.filter(q=>q.subject===subject&&Number(q.points)===points).length,rows=[];for(const x of [['Қазақстан тарихы',20],['Оқу сауаттылығы',10],['Математикалық сауаттылық',10]]){const got=count(x[0],1);rows.push({subject:x[0],need:`${x[1]} × 1 ұпай`,got:`${got} × 1 ұпай`,ok:got>=x[1]})}for(const subject of cfg.untProfiles){const one=count(subject,1),two=count(subject,2);rows.push({subject,need:'30 × 1 + 10 × 2',got:`${one} × 1 + ${two} × 2`,ok:one>=30&&two>=10})}return rows}
function openUntAdmin(){const data=untAdminData(),done=data.attempts.filter(a=>a.submittedAt),avg=done.length?Math.round(done.reduce((sum,a)=>sum+(a.total?Number(a.score)/Number(a.total)*100:0),0)/done.length):0,ready=untReadinessRows(data.questions),ranking=untRankingItems(),subjectOptions='<option value="">Барлық ҰБТ пәні</option>'+[...cfg.untMandatory,...cfg.untProfiles].map(x=>`<option>${h(x)}</option>`).join('');$('dashContent').innerHTML=`<div class="untAdminHead"><div><h3>11-сынып ҰБТ сынағын басқару</h3><p>Олимпиададан бөлек сұрақ қоры, қатысушылар, рейтинг және нәтижелер. Шығармашылық бағыт: 30 тапсырма, 70 минут.</p></div><div><button class="secondary" onclick="openUntImport()">Word / Excel сұрақ қосу</button><button class="secondary" onclick="downloadUntResultsWord()">Рейтингті Word-пен жүктеу</button><button class="danger" onclick="resetUnt()">Жаңа ҰБТ кезеңі</button></div></div><section class="imageManager"><div><h3>Сұрақтарға сурет қосу</h3><p class="muted">Суретті компьютерден жүктеңіз немесе Wikimedia Commons ашық қорынан іздеңіз. Алынған URL мен дереккөзді Excel-дегі тиісті бағандарға қойыңыз.</p></div><div class="imageTools"><label>Компьютерден/телефоннан сурет<input id="questionImages" type="file" multiple accept="image/png,image/jpeg,image/webp"></label><button class="secondary" onclick="uploadQuestionImages()">Суреттерді жүктеу</button></div><div class="imageTools"><label>Ашық дереккөзден іздеу<input id="commonsQuery" placeholder="Мысалы: Қазақстан картасы"></label><button class="secondary" onclick="searchOpenImages()">Іздеу</button></div><div id="imageResults" class="imageResults"></div></section><div class="stats untStats"><div class="stat"><b>${data.students.length}</b><span>ҰБТ қатысушысы</span></div><div class="stat"><b>${done.length}</b><span>Тапсырған</span></div><div class="stat"><b>${data.questions.length}</b><span>ҰБТ сұрағы</span></div><div class="stat"><b>${avg}%</b><span>Орташа нәтиже</span></div></div><h3>Сұрақ қорының дайындығы</h3>${table(['Пән','Бір тестке қажет','Қорда бар','Күйі'],ready.map(x=>`<tr><td>${h(x.subject)}</td><td>${x.need}</td><td>${x.got}</td><td><b class="${x.ok?'bankReady':'bankLow'}">${x.ok?'Дайын':'Жеткіліксіз'}</b></td></tr>`).join(''))}<p class="muted">Шығармашылық бағытқа Қазақстан тарихынан 20 және оқу сауаттылығынан 10 сұрақ жеткілікті.</p><h3 class="analysisTitle">11-сынып ҰБТ рейтингі</h3>${table(['Орын','Оқушы','Бағыты','Балл','Пайыз','Уақыт','Дәлелдеме'],ranking.map(x=>`<tr><td><b>${x.place}</b></td><td>${h(x.s.name)}</td><td>${h(x.s.profile1?.startsWith('Шығармашылық')?'Шығармашылық бағыт':x.s.subject)}</td><td><b>${x.a.score}/${x.a.total}</b></td><td>${x.percent}%</td><td>${Math.floor(x.seconds/60)} мин</td><td><button class="secondary compact" onclick="downloadStudentAnalysis('${x.a.id}')">Жеке Word</button></td></tr>`).join(''))}<div class="untQuestionHead"><h3>Жеке ҰБТ сұрақ қоры</h3><label>Пән<select id="untQuestionSubject" onchange="renderUntQuestions()">${subjectOptions}</select></label></div><div id="untQuestionsArea"></div>`;renderUntQuestions()}
function renderUntQuestions(){const {questions}=untAdminData(),subject=$('untQuestionSubject')?.value||'',items=questions.filter(q=>!subject||q.subject===subject);$('untQuestionsArea').innerHTML=`<div class="questionBankActions"><p class="muted">Көрсетілді: ${items.length} сұрақ.</p><button class="secondary" onclick="downloadUntQuestionBankWord()">Осы қорды суреттерімен Word-пен жүктеу</button></div>`+table(['Пән','Сурет','Сұрақ','Ұпай',''],items.map(q=>`<tr><td>${h(q.subject)}</td><td>${q.image_url?`<img class="questionThumb" src="${h(q.image_url)}" alt="Сурет">`:'—'}</td><td>${h(q.text)}${q.image_source?`<small class="sourceLine">${h(q.image_source)}</small>`:''}</td><td>${q.points}</td><td><button class="danger" onclick="deleteUntQ('${q.id}')">Өшіру</button></td></tr>`).join(''))}
function packImageText(value){return btoa(unescape(encodeURIComponent(String(value||''))))}
function unpackImageText(value){return decodeURIComponent(escape(atob(value)))}
function imageCards(items){return items.map(x=>`<article class="imageCard"><img src="${h(x.imageUrl||x.url)}" alt="${h(x.title||x.name||'Сурет')}" loading="lazy"><div><b>${h(x.title||x.name||'Жүктелген сурет')}</b><small>${h(x.license||x.imageSource||'Өзіңіз жүктеген сурет')}</small><div class="imageCardActions"><button class="secondary compact" onclick="copyImageValue('${packImageText(x.imageUrl||x.url)}')">URL көшіру</button>${x.imageSource?`<button class="secondary compact" onclick="copyImageValue('${packImageText(x.imageSource)}')">Дереккөзді көшіру</button>`:''}${x.sourceUrl?`<button class="primary compact" onclick="saveOpenImage('${packImageText(x.imageUrl)}','${packImageText(x.imageSource)}')">Сайтқа сақтау</button><a href="${h(x.sourceUrl)}" target="_blank" rel="noopener">Дереккөз</a>`:''}</div></div></article>`).join('')}
async function fileBase64(file){return await new Promise((ok,bad)=>{const r=new FileReader();r.onload=()=>ok(String(r.result).split(',')[1]);r.onerror=bad;r.readAsDataURL(file)})}
async function uploadQuestionImages(){const files=[...($('questionImages')?.files||[])].slice(0,50);if(!files.length)return toast('Суреттерді таңдаңыз');try{const images=[];for(const file of files){if(file.size>2e6)return toast(`${file.name}: 2 МБ-тан үлкен`);images.push({name:file.name,type:file.type,data:await fileBase64(file)})}const r=await api('/api/admin/images/upload',{method:'POST',token:adminToken,body:JSON.stringify({images})});$('imageResults').innerHTML=imageCards(r.images);toast(`${r.images.length} сурет жүктелді. URL-ін көшіріңіз.`)}catch(e){toast(e.message)}}
async function searchOpenImages(){const q=$('commonsQuery')?.value.trim();if(!q)return toast('Іздеу сөзін жазыңыз');try{$('imageResults').innerHTML='<p class="muted">Ашық қордан ізделіп жатыр…</p>';const r=await api('/api/admin/images/search?q='+encodeURIComponent(q),{token:adminToken});$('imageResults').innerHTML=r.images.length?imageCards(r.images):'<p class="muted">Сурет табылмады.</p>'}catch(e){$('imageResults').innerHTML='';toast(e.message)}}
async function saveOpenImage(urlCode,sourceCode){try{const r=await api('/api/admin/images/import',{method:'POST',token:adminToken,body:JSON.stringify({imageUrl:unpackImageText(urlCode),imageSource:unpackImageText(sourceCode)})});$('imageResults').insertAdjacentHTML('afterbegin',imageCards([r.image]));toast('Сурет сайттың тұрақты қорына сақталды. Жаңа URL-ді көшіріңіз.')}catch(e){toast(e.message)}}
async function copyImageValue(encoded){const value=unpackImageText(encoded);try{await navigator.clipboard.writeText(value);toast('Көшірілді')}catch{const el=document.createElement('textarea');el.value=value;document.body.appendChild(el);el.select();document.execCommand('copy');el.remove();toast('Көшірілді')}}
async function wordImageData(url){if(!url)return '';try{const r=await fetch(url);if(!r.ok)throw Error();const blob=await r.blob();return await new Promise((ok,bad)=>{const reader=new FileReader();reader.onload=()=>ok(reader.result);reader.onerror=bad;reader.readAsDataURL(blob)})}catch{return url}}
async function downloadUntQuestionBankWord(){const subject=$('untQuestionSubject')?.value||'',questions=untAdminData().questions.filter(q=>!subject||q.subject===subject);if(!questions.length)return toast('Жүктейтін сұрақ жоқ');toast('Word құжаты дайындалып жатыр…');const urls=[...new Set(questions.map(q=>q.image_url).filter(Boolean))],pairs=await Promise.all(urls.map(async u=>[u,await wordImageData(u)])),images=new Map(pairs),rows=questions.map(q=>{const opts=Array.isArray(q.options)?q.options:[],image=q.image_url?`<img src="${h(images.get(q.image_url)||q.image_url)}" width="150"><br><small>${h(q.image_url)}</small>`:'';return `<tr><td>${h(q.subject)}</td><td>${h(q.text)}</td>${[0,1,2,3,4].map(n=>`<td>${h(opts[n]||'')}</td>`).join('')}<td>${answerLetter(q.correct)}</td><td>${q.points||1}</td><td>${image}</td><td>${h(q.image_source||'')}</td></tr>`}).join(''),title=subject||'Барлық ҰБТ пәні',doc=`<!doctype html><html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" lang="kk"><head><meta charset="utf-8"><title>${h(title)} сұрақ қоры</title><style>@page{size:A4 landscape;margin:8mm}body{font:8pt Arial,sans-serif;color:#111}h1{font-size:16pt;text-align:center}p{font-size:9pt}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{border:1px solid #aaa;padding:3px;vertical-align:top;overflow-wrap:anywhere}th{background:#173b69;color:#fff}td:first-child{width:9%}td:nth-child(2){width:23%}td img{display:block;max-width:150px;max-height:100px;object-fit:contain}small{font-size:6pt}</style></head><body><h1>${h(title)} сұрақ қоры</h1><p>Сұрақ саны: ${questions.length}. Құжат сайтқа қайта импорттауға арналған. Бағандардың ретін өзгертпеңіз.</p><table><thead><tr><th>Пән</th><th>Сұрақ</th><th>A</th><th>B</th><th>C</th><th>D</th><th>E</th><th>Дұрыс жауап</th><th>Ұпай</th><th>Сурет URL</th><th>Сурет дереккөзі</th></tr></thead><tbody>${rows}</tbody></table></body></html>`;wordDownload(`ҰБТ_сұрақ_қоры_${(subject||'барлық-пән').replace(/[^\p{L}\p{N}]+/gu,'_')}.doc`,doc)}
function downloadUntResultsWord(){const d=window.dash,items=untRankingItems();if(!items.length)return toast('ҰБТ нәтижелері әлі жоқ');const rows=items.map(x=>`<tr><td class="center">${x.place}</td><td>${h(x.s.name)}</td><td>${h(studentDirection(x.s))}</td><td class="center">${x.a.score}/${x.a.total}</td><td class="center">${x.percent}%</td><td class="center">${Math.floor(x.seconds/60)} мин ${x.seconds%60} сек</td></tr>`).join(''),body=`<h1>${h(d.settings.school||'Егемқұл Тасанбаев атындағы ЖББМ')}</h1><h2>11-СЫНЫП ҰБТ ДАЙЫНДЫҚ СЫНАҚ НӘТИЖЕЛЕРІ</h2><p class="center">Құжат жасалған күн: ${new Date().toLocaleString('kk-KZ')}</p><table><thead><tr><th>Орын</th><th>Оқушы</th><th>Бағыты</th><th>Балл</th><th>Пайыз</th><th>Уақыт</th></tr></thead><tbody>${rows}</tbody></table><p>Бұл мектепішілік дайындық сынағы, ресми ҰБТ сертификаты емес.</p>`;wordDownload(`ҰБТ_11-сынып_рейтингі_${new Date().toISOString().slice(0,10)}.doc`,wordDocument(body,'11-сынып ҰБТ рейтингі'))}
async function deleteUntQ(id){if(!confirm('ҰБТ сұрағы өшірілсін бе?'))return;await api('/api/admin/questions/'+id,{method:'DELETE',token:adminToken});await loadDash();dashTab('unt')}
async function resetUnt(){if(!confirm('Барлық ҰБТ қатысушылары мен нәтижелері өшіріледі. ҰБТ сұрақ қоры сақталады. Жалғастырамыз ба?'))return;try{const r=await api('/api/admin/unt/participants',{method:'DELETE',token:adminToken});toast(`${r.removedStudents} ҰБТ қатысушысы және ${r.removedAttempts} нәтиже өшірілді`);await loadDash();dashTab('unt')}catch(e){toast(e.message)}}
function hideModalForms(){['manualForm','aiForm','importForm'].forEach(id=>$(id).classList.add('hidden'))}
function openQuestion(){hideModalForms();$('manualForm').classList.remove('hidden');$('opts').innerHTML=['A','B','C','D'].map((x,i)=>`<label>${x} жауабы<input id="opt${i}"></label>`).join('');$('modal').classList.remove('hidden')}
function openAI(){hideModalForms();$('aiForm').classList.remove('hidden');$('modal').classList.remove('hidden')}
function openImport(){importMode='olympiad';hideModalForms();$('importForm').classList.remove('hidden');$('importTitle').textContent='Олимпиада сұрақтарын Word немесе Excel арқылы қосу';$('importHelp').textContent='Бағандар: Сынып, Пән, Сұрақ, A, B, C, D, Дұрыс жауап, Сурет URL, Сурет дереккөзі. Соңғы екі баған міндетті емес.';$('importFile').value='';$('modal').classList.remove('hidden')}
function openUntImport(){importMode='unt';hideModalForms();$('importForm').classList.remove('hidden');$('importTitle').textContent='ҰБТ сұрақтарын бөлек қорға қосу';$('importHelp').textContent='Бағандар: Пән, Сұрақ, A, B, C, D, E, Дұрыс жауап, Ұпай, Сурет URL, Сурет дереккөзі. E және сурет бағандары міндетті емес; Ұпай 1 немесе 2.';$('importFile').value='';$('modal').classList.remove('hidden')}
function closeModal(){$('modal').classList.add('hidden')}
async function generateAI(){const btn=$('aiBtn');try{btn.disabled=true;btn.textContent='AI дайындап жатыр...';const r=await api('/api/admin/ai-generate',{method:'POST',token:adminToken,body:JSON.stringify({grade:$('aiGrade').value,subject:$('aiSubject').value,count:$('aiCount').value,language:$('aiLanguage').value})});closeModal();toast(`${r.count} сұрақ дайындалды`);loadDash()}catch(e){toast(e.message)}finally{btn.disabled=false;btn.textContent='Сұрақтарды дайындау'}}
async function saveQuestion(){try{await api('/api/admin/questions',{method:'POST',token:adminToken,body:JSON.stringify({grade:$('qGrade').value,subject:$('qSubject').value,text:$('qText').value,options:[0,1,2,3].map(i=>$('opt'+i).value),correct:$('qCorrect').value,points:1,imageUrl:$('qImageUrl').value,imageSource:$('qImageSource').value})});closeModal();toast('Сұрақ сақталды');loadDash()}catch(e){toast(e.message)}}
async function importQuestions(){const file=$('importFile').files[0],btn=$('importBtn'),mode=importMode;if(!file)return toast('Файлды таңдаңыз');try{btn.disabled=true;btn.textContent='Импортталып жатыр...';const data=await new Promise((ok,bad)=>{const r=new FileReader();r.onload=()=>ok(String(r.result).split(',')[1]);r.onerror=bad;r.readAsDataURL(file)}),endpoint=mode==='unt'?'/api/admin/unt/questions/import':'/api/admin/questions/import',x=await api(endpoint,{method:'POST',token:adminToken,body:JSON.stringify({name:file.name,data})});closeModal();toast(`${x.count} сұрақ қосылды${x.skipped?`, ${x.skipped} жол өткізілді`:''}`);await loadDash();if(mode==='unt')dashTab('unt')}catch(e){toast(e.message)}finally{btn.disabled=false;btn.textContent='Сұрақтарды импорттау'}}
async function deleteQ(id){if(!confirm('Сұрақ өшірілсін бе?'))return;await api('/api/admin/questions/'+id,{method:'DELETE',token:adminToken});loadDash()}
async function saveJury(){try{const jury=juryValues(),settings=await api('/api/admin/settings',{method:'POST',token:adminToken,body:JSON.stringify({jury})});window.dash.settings=settings;toast('Қазылар алқасы сақталды')}catch(e){toast(e.message)}}
async function resetOlympiad(){if(!confirm('Барлық қатысушылар мен олардың нәтижелері (хаттамалары) өшіріледі. Сұрақтар қоры сақталады. Жаңа олимпиада бастаймыз ба?'))return;try{const r=await api('/api/admin/participants',{method:'DELETE',token:adminToken});toast(`${r.removedStudents} қатысушы және ${r.removedAttempts} нәтиже өшірілді`);await loadDash()}catch(e){toast(e.message)}}
async function saveSettings(){await api('/api/admin/settings',{method:'POST',token:adminToken,body:JSON.stringify({school:$('setSchool').value,durationMinutes:$('setDuration').value})});toast('Баптаулар сақталды');loadDash()}
function juryProtocolHtml(source){const j=juryValues(),chair=h(j.chair)||'________________________________________',secretary=h(j.secretary)||'________________________________________',members=h(j.members||'________________________________________').replace(/\n/g,'<br>');return String(source).replace('Олимпиада комиссиясының төрағасы: __________________________________________',`Олимпиада комиссиясының төрағасы: <b>${chair}</b>`).replace('Комиссия мүшелері: _________________________________________________________',`Комиссия мүшелері: <b>${members}</b>`).replace('Хатшы: ____________________________________________________________________',`Хатшы: <b>${secretary}</b>`).replace('Олимпиада комиссиясының төрағасы: ____________________ / __________ /',`Олимпиада комиссиясының төрағасы: ${chair} / __________ /`).replace('Комиссия мүшелері: __________________________________ / __________ /',`Комиссия мүшелері: ${members} / __________ /`).replace('Хатшы: ______________________________________________ / __________ /',`Хатшы: ${secretary} / __________ /`)}
const printProtocolBase=printProtocol;printProtocol=function(){let popup;const nativeOpen=window.open;window.open=(...args)=>(popup=nativeOpen(...args));try{printProtocolBase()}finally{window.open=nativeOpen}if(popup){const html=popup.document.documentElement.outerHTML;popup.document.open();popup.document.write(juryProtocolHtml(html));popup.document.close()}}
const downloadProtocolWordBase=downloadProtocolWord;downloadProtocolWord=function(){const NativeBlob=window.Blob;window.Blob=function(parts,options){return new NativeBlob(parts.map(x=>typeof x==='string'?juryProtocolHtml(x):x),options)};window.Blob.prototype=NativeBlob.prototype;try{downloadProtocolWordBase()}finally{window.Blob=NativeBlob}}
init().catch(e=>toast(e.message));
